import {useChildRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {useFeatureFlag} from '@github-ui/react-core/use-feature-flag'
import type {ReposFilterProps} from '@github-ui/repos-filter'
import type {SidebarLink} from '@github-ui/saved-views'
import {getShortcutsWithSaved, useShortcutDeletion, useShortcutEditor} from '@github-ui/saved-views'
import {useEffect, useState} from 'react'

import {getItemById, getItemFromQuery} from '../components/FinderSidebar'
import {useReposFinderStateContext} from '../contexts/ReposFinderStateContext'
import {reposFinderPageRoute} from '../routes/repos-finder-page-route'

/**
 * Hook to manage the state of the repos finder layout, including query state,
 * repository shortcuts, and sidebar selection. Gets data from context rather than props.
 * Provides methods for updating and submitting queries, managing shortcuts, and selecting sidebar links.
 *
 * @returns An object containing:
 *   - shortcuts: Array of repository shortcuts
 *   - selectedSidebarItem: Currently selected sidebar link
 *   - editing: Shortcut editing state and methods
 *   - deleting: Shortcut deletion state and methods
 *   - methods: Object with selectSidebarLink, createShortcut, editShortcut, and fetchResults functions
 *   - reposFilterProps: Props for the repository filter component
 */
export function useReposFinderLayoutState() {
  const {payload, fetchedQuery, queryParam, fetchResults, locationSidebarItemId, hasLocationState} =
    useReposFinderStateContext()

  const [query, setQuery] = useState(queryParam)

  const [shortcuts, setShortcuts] = useState(() =>
    payload.repoShortcuts.map(shortcut => ({...shortcut, searchType: 'repositories'}) as SidebarLink),
  )

  function deriveSidebarItem(q: string, sidebarItemId: string | undefined, fromState: boolean) {
    if (fromState) {
      return sidebarItemId ? getItemById(sidebarItemId, shortcuts) : undefined
    }
    return getItemFromQuery(q, shortcuts)
  }

  const [selectedSidebarItem, setSelectedSidebarItem] = useState<SidebarLink | undefined>(() =>
    deriveSidebarItem(query, locationSidebarItemId, hasLocationState),
  )

  useEffect(() => {
    setQuery(queryParam)
    setSelectedSidebarItem(deriveSidebarItem(queryParam, locationSidebarItemId, hasLocationState))
    // eslint-disable-next-line react-hooks/exhaustive-deps -- Only revert query & sidebar item upon navigation
  }, [queryParam, locationSidebarItemId, hasLocationState])

  const onShortcutDeleted = (deletedShortcut: SidebarLink) => {
    setShortcuts(shortcuts.filter(shortcut => shortcut.id !== deletedShortcut.id))
    setSelectedSidebarItem(undefined)
  }
  const deleting = useShortcutDeletion(onShortcutDeleted)

  const onShortcutSaved = (savedShortcut: SidebarLink) => {
    setShortcuts(getShortcutsWithSaved(shortcuts, savedShortcut))

    if (fetchedQuery !== savedShortcut.query) {
      fetchResults({q: savedShortcut.query, page: 1, sidebarItemId: savedShortcut.id})
    } else {
      setSelectedSidebarItem(savedShortcut)
    }
  }
  const editing = useShortcutEditor({type: 'repositories', onShortcutSaved})

  const {data: pagePayload} = useChildRouteQuery(reposFinderPageRoute, 'mainQuery')
  /* eslint-disable-next-line @github-ui/github-monorepo/no-use-feature-flags --
     TODO: Migrate to isFeatureEnabled from @github-ui/feature-flags. See
     https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
  const showFilterDialog = useFeatureFlag('repos_list_show_filter_dialog')

  const definitions = pagePayload?.customProperties?.definitions ?? []
  const includeDeploymentProperties = pagePayload?.includeDeploymentProperties ?? false

  function updateQuery(q: string) {
    setQuery(q)
    if (editing.shortcut) {
      editing.setValue('query', q)
    }
  }

  async function kindlyDismissEditing() {
    if (editing.shortcut) {
      const dismissed = await editing.dismiss()
      if (!dismissed) return false
    }
    return true
  }

  async function selectSidebarLink(linkItem: SidebarLink) {
    if (!(await kindlyDismissEditing())) return
    deleting.reset()

    fetchResults({q: linkItem.query, page: 1, sidebarItemId: linkItem.id})
  }

  async function createShortcut() {
    if (!(await kindlyDismissEditing())) return

    setSelectedSidebarItem(undefined)
    deleting.reset()
    editing.create(query, selectedSidebarItem)
  }

  function editShortcut(shortcut: SidebarLink) {
    deleting.reset()
    editing.edit(shortcut, query)
  }

  function updateShortcut(shortcut: SidebarLink) {
    deleting.reset()
    editing.updateQuery(shortcut, fetchedQuery)
  }

  const reposFilterProps: ReposFilterProps = {
    options: {
      withOwnerTerms: true,
      withFinderTerms: true,
      withRelevanceSort: true,
      includeDeploymentProperties,
    },
    id: 'repos-finder-filter',
    label: 'Search repositories',
    variant: showFilterDialog ? 'full' : 'input',
    placeholder: 'Search repositories',
    filterValue: query,
    orgs: payload.suggestedOrgs,
    definitions,
    onChange: updateQuery,
    onSubmit: filterQuery => fetchResults({q: filterQuery.raw, page: 1, sidebarItemId: selectedSidebarItem?.id || ''}),
  }

  return {
    shortcuts,
    selectedSidebarItem,
    editing,
    deleting,
    methods: {
      selectSidebarLink,
      createShortcut,
      editShortcut,
      updateShortcut,
      fetchResults,
    },
    reposFilterProps,
  }
}
